class Solution:
    def canBeEqual(self, target: list[int], arr: list[int]) -> bool:
        return sorted(target) == sorted(arr)

matrix-diagonal-sum:
class Solution:
    def diagonalSum(self, mat: list[list[int]]) -> int:
        n = len(mat)
        total = 0
        for i in range(n):
            total += mat[i][i] + mat[i][n - 1 - i]
        if n % 2 == 1:
            total -= mat[n // 2][n // 2]
        return total

maximum-difference-between-increasing-el:
class Solution:
    def maximumDifference(self, nums: list[int]) -> int:
        best = -1
        low = nums[0]
        for i in range(1, len(nums)):
            if nums[i] > low:
                if nums[i] - low > best:
                    best = nums[i] - low
            else:
                low = nums[i]
        return best

maximum-nesting-depth-of-the-parentheses:
class Solution:
    def maxDepth(self, s: str) -> int:
        d = 0
        best = 0
        for c in s:
            if c == '(':
                d += 1
                if d > best:
                    best = d
            elif c == ')':
                d -= 1
        return best

maximum-number-of-balls-in-a-box:
class Solution:
    def countBalls(self, lowLimit: int, highLimit: int) -> int:
        cnt = {}
        for n in range(lowLimit, highLimit + 1):
            total = 0
            x = n
            while x:
                total += x % 10
                x //= 10
            cnt[total] = cnt.get(total, 0) + 1
        return max(cnt.values())

maximum-number-of-words-you-can-type:
class Solution:
    def canBeTypedWords(self, text: str, brokenLetters: str) -> int:
        bad = set(brokenLetters)
        cnt = 0
        for w in text.split():
            ok = True
            for c in w:
                if c in bad:
                    ok = False
                    break
            if ok:
                cnt += 1
        return cnt

maximum-population-year:
class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        diff = {}
        for b, d in logs:
            diff[b] = diff.get(b, 0) + 1
            diff[d] = diff.get(d, 0) - 1
        best = 0
        best_year = 0
        cur = 0
        for y in range(1950, 2051):
            cur += diff.get(y, 0)
            if cur > best:
                best = cur
                best_year = y
        return best_year

maximum-product-difference-between-two-p:
class Solution:
    def maxProductDifference(self, nums: list[int]) -> int:
        nums = sorted(nums)
        return nums[-1] * nums[-2] - nums[0] * nums[1]

maximum-product-of-two-elements-in-an-ar:
class Solution:
    def maxProduct(self, nums: list[int]) -> int:
        best = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                v = (nums[i] - 1) * (nums[j] - 1)
                if v > best:
                    best = v
        return best
